import React, { useState } from 'react';
import Icon from 'components/AppIcon';
import { useGoals } from '../../../contexts/GoalsContext';

const GoalForm = ({ onClose }) => {
  const { createGoal } = useGoals();
  const [form, setForm] = useState({
    title: '',
    description: '',
    targetType: 'hours',
    targetValue: 10,
    deadline: '',
  });
  const [saving, setSaving] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      await createGoal(form);
      onClose();
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
      <div className="bg-surface border border-border rounded-lg w-full max-w-md p-6">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-lg font-heading font-semibold">New Learning Goal</h2>
          <button onClick={onClose}><Icon name="X" size={20} /></button>
        </div>
        <form onSubmit={handleSubmit} className="space-y-4">
          <input
            className="input w-full"
            placeholder="Goal title"
            value={form.title}
            onChange={(e) => setForm({ ...form, title: e.target.value })}
            required
          />
          <textarea
            className="input w-full min-h-[60px]"
            placeholder="Description (optional)"
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
          />
          <div className="grid grid-cols-2 gap-3">
            <select
              className="input"
              value={form.targetType}
              onChange={(e) => setForm({ ...form, targetType: e.target.value })}
            >
              <option value="hours">Hours</option>
              <option value="modules">Modules</option>
              <option value="streak">Streak days</option>
              <option value="score">Completion %</option>
            </select>
            <input
              type="number"
              className="input"
              min={1}
              value={form.targetValue}
              onChange={(e) => setForm({ ...form, targetValue: Number(e.target.value) })}
              required
            />
          </div>
          <input
            type="date"
            className="input w-full"
            value={form.deadline}
            onChange={(e) => setForm({ ...form, deadline: e.target.value })}
          />
          <button type="submit" disabled={saving} className="btn btn-primary w-full py-2">
            {saving ? 'Creating...' : 'Create Goal'}
          </button>
        </form>
      </div>
    </div>
  );
};

export default GoalForm;
