import React from 'react';
import Icon from 'components/AppIcon';
import { useGoals } from '../../../contexts/GoalsContext';

const TARGET_LABELS = {
  hours: 'learning hours',
  modules: 'modules completed',
  streak: 'day streak',
  score: '% completion',
};

const GoalCard = ({ goal, onUpdate }) => {
  const { deleteGoal } = useGoals();
  const pct = goal.targetValue
    ? Math.min(100, Math.round(((goal.currentValue || 0) / goal.targetValue) * 100))
    : 0;

  return (
    <div className={`card p-5 ${goal.status === 'completed' ? 'border-success' : ''}`}>
      <div className="flex items-start justify-between gap-4 mb-3">
        <div>
          <h3 className="font-heading font-semibold text-text-primary">{goal.title}</h3>
          {goal.description && (
            <p className="text-sm text-text-secondary mt-1">{goal.description}</p>
          )}
        </div>
        {goal.status === 'completed' && (
          <Icon name="CheckCircle" size={24} className="text-success shrink-0" />
        )}
      </div>
      <div className="mb-2 flex justify-between text-sm">
        <span className="text-text-secondary">
          {goal.currentValue || 0} / {goal.targetValue} {TARGET_LABELS[goal.targetType] || goal.targetType}
        </span>
        <span className="font-medium">{pct}%</span>
      </div>
      <div className="w-full bg-surface-100 rounded-full h-2 mb-3">
        <div className="bg-primary h-2 rounded-full transition-all" style={{ width: `${pct}%` }} />
      </div>
      {goal.deadline && (
        <p className="text-xs text-text-secondary mb-3">Deadline: {goal.deadline}</p>
      )}
      {goal.status === 'active' && (
        <button
          onClick={() => deleteGoal(goal.id).then(onUpdate)}
          className="text-xs text-error hover:underline"
        >
          Delete goal
        </button>
      )}
    </div>
  );
};

export default GoalCard;
