import React, { useState } from 'react';
import Icon from 'components/AppIcon';
import { useGoals } from '../../contexts/GoalsContext';
import LoadingState from '../../components/ui/LoadingState';
import GoalForm from './components/GoalForm';
import GoalCard from './components/GoalCard';

const GoalsPage = () => {
  const { activeGoals, completedGoals, loading, refresh } = useGoals();
  const [showForm, setShowForm] = useState(false);

  if (loading) return <LoadingState message="Loading goals..." />;

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8 max-w-3xl">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h1 className="text-2xl lg:text-3xl font-heading font-bold text-text-primary">Learning Goals</h1>
            <p className="text-text-secondary mt-1">Track milestones and stay motivated</p>
          </div>
          <button onClick={() => setShowForm(true)} className="btn btn-primary px-4 py-2">
            <Icon name="Plus" size={16} className="mr-2" />
            New Goal
          </button>
        </div>

        <section className="mb-10">
          <h2 className="text-lg font-heading font-semibold mb-4">Active ({activeGoals.length})</h2>
          {activeGoals.length === 0 ? (
            <p className="text-text-secondary card p-6 text-center">No active goals. Create one to get started.</p>
          ) : (
            <div className="space-y-4">
              {activeGoals.map((goal) => (
                <GoalCard key={goal.id} goal={goal} onUpdate={refresh} />
              ))}
            </div>
          )}
        </section>

        {completedGoals.length > 0 && (
          <section>
            <h2 className="text-lg font-heading font-semibold mb-4">Completed ({completedGoals.length})</h2>
            <div className="space-y-4">
              {completedGoals.map((goal) => (
                <GoalCard key={goal.id} goal={goal} onUpdate={refresh} />
              ))}
            </div>
          </section>
        )}

        {showForm && <GoalForm onClose={() => setShowForm(false)} />}
      </div>
    </div>
  );
};

export default GoalsPage;
